 product=json.loads((root/manifests[1]).read_text(encoding='utf-8-sig')); cases=product.get('cases',[]); ids=[c.get('case_id') for c in cases]
 return {'tracked':tracked_hashes,'pins':pins,'product_case_count':len(cases),'product_case_ids_unique':len(ids)==len(set(ids)),'api26_case':[c for c in cases if c.get('case_id')=='API-26'],'ui09_case':[c for c in cases if c.get('case_id')=='UI-09']}
