summary={'classification':'PYTHON_MANIFEST_REGRESSION_NOT_PILOTQUOTA_GO_PACKAGE','command':cmd,'cwd':str(root),'python':sys.version,'exit_code':p.returncode,'elapsed_seconds':elapsed,'stdout_bytes':len(p.stdout),'stderr_bytes':len(p.stderr),'tracked_hashes_stable':before['tracked']==after['tracked'],'source_hash_pin_count_before':len(before['pins']),'source_hash_pins_all_match_before':all(x['match'] for x in before['pins']),'source_hash_pin_count_after':len(after['pins']),'source_hash_pins_all_match_after':all(x['match'] for x in after['pins']),'product_case_count_before':before['product_case_count'],'product_case_count_after':after['product_case_count'],'product_case_ids_unique_before':before['product_case_ids_unique'],'product_case_ids_unique_after':after['product_case_ids_unique'],'api26_case_present':len(after['api26_case'])==1,'ui09_case_present':len(after['ui09_case'])==1,'api26_test_name_present':'api26' in src,'ui09_test_name_present':'ui09' in src,'api26_test_passed':('test_api26_' in stderr and '... ok' in stderr[stderr.find('test_api26_'):stderr.find('\n',stderr.find('test_api26_'))+1]),'ui09_test_passed':('test_ui09_' in stderr and '... ok' in stderr[stderr.find('test_ui09_'):stderr.find('\n',stderr.find('test_ui09_'))+1]),'candidate_execution_invoked':False}
(out/'summary.json').write_text(json.dumps(summary,indent=2)+'\n',encoding='utf-8');print(json.dumps({k:summary[k] for k in ('exit_code','elapsed_seconds','tracked_hashes_stable','source_hash_pin_count_before','source_hash_pins_all_match_before','source_hash_pin_count_after','source_hash_pins_all_match_after','product_case_count_before','product_case_count_after','product_case_ids_unique_after','api26_test_passed','ui09_test_passed','candidate_execution_invoked')},indent=2))
